#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GuiWidgetKind {
    Panel,
    TextInput,
    TextArea,
    PasswordInput,
    Checkbox,
    Select,
    NumericInput,
    ReadOnly,
    Button,
    List,
    ListItem,
    Status,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct GuiWidgetNode {
    id: String,
    label: String,
    kind: GuiWidgetKind,
    value: Option<String>,
    enabled: bool,
    selected: bool,
    children: Vec<GuiWidgetNode>,
}

impl GuiWidgetNode {
    fn leaf(
        id: impl Into<String>,
        label: impl Into<String>,
        kind: GuiWidgetKind,
        value: Option<String>,
        enabled: bool,
        selected: bool,
    ) -> Self {
        Self {
            id: id.into(),
            label: label.into(),
            kind,
            value,
            enabled,
            selected,
            children: Vec::new(),
        }
    }

    fn branch(
        id: impl Into<String>,
        label: impl Into<String>,
        kind: GuiWidgetKind,
        children: Vec<GuiWidgetNode>,
    ) -> Self {
        Self {
            id: id.into(),
            label: label.into(),
            kind,
            value: None,
            enabled: true,
            selected: false,
            children,
        }
    }

    fn find(&self, id: &str) -> Option<&Self> {
        if self.id == id {
            return Some(self);
        }
        self.children.iter().find_map(|child| child.find(id))
    }

    fn node_count(&self) -> usize {
        1 + self
            .children
            .iter()
            .map(GuiWidgetNode::node_count)
            .sum::<usize>()
    }

    fn render_with(&self, renderer: &mut impl GuiWidgetRenderer) {
        self.render_with_depth(renderer, 0);
    }

    fn render_with_depth(&self, renderer: &mut impl GuiWidgetRenderer, depth: usize) {
        renderer.begin_node(self, depth);
        for child in &self.children {
            child.render_with_depth(renderer, depth + 1);
        }
        renderer.end_node(self, depth);
    }
}

trait GuiWidgetRenderer {
    fn begin_node(&mut self, node: &GuiWidgetNode, depth: usize);

    fn end_node(&mut self, node: &GuiWidgetNode, depth: usize);
}

trait GuiAppHost {
    type Output;

    fn render(&mut self, state: SyncplayGuiShellAppState) -> Self::Output;
}

impl GuiWidgetKind {
    #[cfg(test)]
    fn label(self) -> &'static str {
        match self {
            Self::Panel => "panel",
            Self::TextInput => "text-input",
            Self::TextArea => "text-area",
            Self::PasswordInput => "password-input",
            Self::Checkbox => "checkbox",
            Self::Select => "select",
            Self::NumericInput => "numeric-input",
            Self::ReadOnly => "read-only",
            Self::Button => "button",
            Self::List => "list",
            Self::ListItem => "list-item",
            Self::Status => "status",
        }
    }
}

