#[cfg(test)]
fn startup_preview(settings: &StoredClientSettingsMvp) -> String {
    let mut host = GuiTextPreviewHost;
    run_gui_host(settings, &mut host)
}

#[cfg(test)]
fn run_gui_host<Host: GuiAppHost>(
    settings: &StoredClientSettingsMvp,
    host: &mut Host,
) -> Host::Output {
    run_gui_host_with_startup_actions(settings, Vec::new(), host)
}

fn run_gui_host_with_startup_actions_and_gui_state<Host: GuiAppHost>(
    settings: &StoredClientSettingsMvp,
    persisted_ui_state: Option<&GuiPersistedUiState>,
    startup_actions: Vec<GuiShellAction>,
    host: &mut Host,
) -> Host::Output {
    let mut startup_settings = settings.clone();
    if let Some(persisted_ui_state) = persisted_ui_state {
        persisted_ui_state.merge_into_startup_settings(&mut startup_settings);
    }
    let mut state = SyncplayGuiShellAppState::from_stored_settings(&startup_settings);
    if let Some(persisted_ui_state) = persisted_ui_state {
        state.apply_persisted_ui_state(persisted_ui_state);
    }
    for action in startup_actions {
        state.apply(action);
    }
    host.render(state)
}

fn run_gui_host_with_startup_actions<Host: GuiAppHost>(
    settings: &StoredClientSettingsMvp,
    startup_actions: Vec<GuiShellAction>,
    host: &mut Host,
) -> Host::Output {
    run_gui_host_with_startup_actions_and_gui_state(settings, None, startup_actions, host)
}

fn optional_text(value: Option<&str>) -> &str {
    value
        .filter(|text| !text.trim().is_empty())
        .unwrap_or("(unset)")
}

fn optional_string_list_text(value: Option<&[String]>) -> String {
    value
        .filter(|entries| !entries.is_empty())
        .map(|entries| entries.join("; "))
        .unwrap_or_else(|| "(unset)".to_owned())
}

fn parse_trusted_domains_text(value: &str) -> Option<Vec<String>> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return None;
    }
    if trimmed.starts_with('[') != trimmed.ends_with(']') {
        return None;
    }
    parse_serialized_string_list_legacy_compatible(trimmed)
}

fn optional_port_text(value: Option<u16>) -> String {
    value.map_or_else(|| "(unset)".to_owned(), |value| value.to_string())
}

fn optional_seconds_text(value: Option<f64>) -> String {
    value.map_or_else(|| "(unset)".to_owned(), |value| format!("{value:.2}s"))
}

fn optional_f64_text(value: Option<f64>) -> String {
    value.map_or_else(|| "(unset)".to_owned(), |value| value.to_string())
}

fn optional_i64_text(value: Option<i64>) -> String {
    value.map_or_else(|| "(unset)".to_owned(), |value| value.to_string())
}

fn optional_index_text(value: Option<usize>) -> String {
    value.map_or_else(|| "(none)".to_owned(), |value| value.to_string())
}

fn bool_label(value: bool) -> &'static str {
    if value { "yes" } else { "no" }
}

fn normalized_editable_text(value: &str) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.is_empty() || trimmed == "(unset)" {
        None
    } else {
        Some(trimmed.to_owned())
    }
}

#[allow(dead_code)]
fn main() {
    match run_syncplay_gui_semantic_cli_from_env() {
        Ok(Some(output)) => {
            println!("{output}");
            return;
        }
        Ok(None) => {}
        Err(error) => {
            eprintln!("syncplay-gui failed to run semantic scenario: {error}");
            std::process::exit(1);
        }
    }
    let (mut host, settings) = match gui_startup_host_and_settings() {
        Ok(startup) => startup,
        Err(error) => {
            eprintln!("syncplay-gui failed to configure startup runtime: {error}");
            std::process::exit(1);
        }
    };
    let persisted_ui_state = match load_gui_ui_state_from_lookup(&env_trimmed) {
        Ok(state) => state,
        Err(error) => {
            eprintln!("syncplay-gui failed to load legacy GUI state: {error}");
            std::process::exit(1);
        }
    };
    let mut merged_settings = settings.clone();
    if let Some(persisted_ui_state) = persisted_ui_state.as_ref() {
        persisted_ui_state.merge_into_startup_settings(&mut merged_settings);
    }
    let startup_actions = gui_startup_actions_from_lookup(env_trimmed, &merged_settings);
    if let Err(error) = run_gui_host_with_startup_actions_and_gui_state(
        &settings,
        persisted_ui_state.as_ref(),
        startup_actions,
        &mut host,
    ) {
        eprintln!("syncplay-gui failed to start: {error}");
        std::process::exit(1);
    }
}

